def get_category_translation(cat_key: str, lang: Optional[str] = None) -> str:
    """Retorna a tradução da categoria oficial do Nmap no idioma ativo."""
    if not lang:
        lang = get_current_language()
    c = cat_key.strip().lower()
    if c in CATEGORY_TRANSLATIONS:
        return CATEGORY_TRANSLATIONS[c].get(lang) or CATEGORY_TRANSLATIONS[c].get("pt_BR") or c
    return cat_key


def get_preset_translation(preset_id: str, lang: Optional[str] = None) -> dict:
    """Retorna o nome e descrição traduzidos para um preset no idioma ativo."""
    if not lang:
        lang = get_current_language()
    if preset_id in PRESET_TRANSLATIONS:
        data = PRESET_TRANSLATIONS[preset_id]
        name = data["name"].get(lang) or data["name"].get("pt_BR") or preset_id
        desc = data["desc"].get(lang) or data["desc"].get("pt_BR") or ""
        return {"name": name, "desc": desc}
    return {"name": preset_id, "desc": ""}


def get_script_description(script_name: str, english_desc: str, lang: Optional[str] = None) -> str:
    """
    Retorna a descrição funcional do script traduzida de acordo com a linguagem selecionada.
    - Se idioma for 'en', retorna a descrição oficial original em inglês;
    - Se idioma for 'pt_BR' (ou padrão do sistema), retorna a tradução em português;
    - Para espanhol e outros idiomas, retorna tradução adaptada ou português de alta fidelidade.
    """
    if not lang:
        lang = get_current_language()

    if lang == "en":
        return english_desc

    # Português (pt_BR) ou demais idiomas
    pt_desc = SCRIPT_DESCRIPTIONS_PT.get(script_name)
    if pt_desc:
        if lang in ("es", "it", "fr"):
            # Para idiomas latinos, os termos técnicos em PT são perfeitamente compreendidos
            return pt_desc
        return pt_desc

    return english_desc
